-- Local executors: metadata for ranking; no provider prompts or selected contents.
on conflict (id) do update set title=excluded.title,description=excluded.description,when_to_offer=excluded.when_to_offer,when_to_avoid=excluded.when_to_avoid,accepted_inputs=excluded.accepted_inputs,output_kind=excluded.output_kind,is_recommendable=excluded.is_recommendable;
