insert into public.action_definitions (id,title,description,when_to_offer,when_to_avoid,accepted_inputs,output_kind,positive_examples,negative_examples,is_recommendable) values
('rename_file','Rename','Suggest a filename from readable local content, allow editing, preview the new name and preserve the extension.','One regular file selected in Finder.','Unavailable cloud files, directories and symbolic links.',ARRAY['file'],'review','[]'::jsonb,'[]'::jsonb,true),
('batch_rename','Batch rename','Preview every before/after filename using an editable template with {original} and {n}, then rename without overwriting.','Several regular files selected in Finder.','Duplicate target names or existing target files.',ARRAY['files'],'review','[]'::jsonb,'[]'::jsonb,true),
('move_files','Move files','Choose a folder or a recent destination, then move the selected files after validation. Recent folder paths remain on this Mac.','Downloaded files that need organizing.','Missing or symbolic-link destinations, unavailable files, filename collisions.',ARRAY['files'],'review','[]'::jsonb,'[]'::jsonb,true),
('compress_files','Compress','Create a ZIP sibling from selected regular files, retaining originals.','One or more files to package together.','Directories, more than 20 files or repeated basenames.',ARRAY['files'],'new_files','[]'::jsonb,'[]'::jsonb,true),
('extract_archive','Extract archive','Extract a supported ZIP into a new named folder after validating paths and regular entries.','One downloaded ZIP archive selected in Finder.','Encrypted ZIP, ZIP64, links, unsafe paths, unsupported archives, more than 1000 entries or 500 MB expanded.',ARRAY['zip'],'new_files','[]'::jsonb,'[]'::jsonb,true),
('compress_images','Compress images','Preview actual encoded JPEG size at a chosen quality or per-image KB target, then create smaller sibling copies.','Downloaded static images to reduce their file size.','Animation, more than 40 MP, targets impossible at current dimensions, outputs larger than originals.',ARRAY['image_files'],'new_files','[]'::jsonb,'[]'::jsonb,true),
('extract_text','Extract text','Read embedded PDF text or recognize image/scanned PDF text locally, displaying a reading card without automatic copying.','One image or a PDF with at most 50 pages.','Locked PDFs, unsupported formats, unreadable or oversized files.',ARRAY['image','pdf'],'reading_card','[]'::jsonb,'[]'::jsonb,true),
('merge_pdfs','Merge PDFs','Review and change document order before creating a merged PDF copy.','Multiple unlocked PDFs selected in Finder.','More than 300 combined pages or an existing output filename.',ARRAY['pdf_files'],'new_files','[]'::jsonb,'[]'::jsonb,true),
('extract_pdf_pages','Extract PDF pages','Enter page numbers or ranges, preview pages, and create a separate PDF in that order.','One unlocked PDF with specific pages to extract.','Missing or invalid page numbers, locked documents or more than 300 pages.',ARRAY['pdf'],'new_files','[]'::jsonb,'[]'::jsonb,true)
